patch.content:
/ {
	aliases {
		i2c-0 = &i2c0;
	};

	i2c0: i2c@400 {
		compatible = "zephyr,i2c-emul-controller";
		reg = <0x400 0x100>;
		#address-cells = <1>;
		#size-cells = <1>;
		status = "okay";

		i2c_emul_0: i2c_emul_0@10 {
			compatible = "zephyr,i2c-emul-eeprom";
			reg = <0x10>;
		};

		i2c_emul_1: i2c_emul_1@20 {
			compatible = "zephyr,i2c-emul-eeprom";
			reg = <0x20>;
		};
	};
};
